<script setup lang="ts">
import {useFixedDockHeight} from '../../shared/composables/useFixedDockHeight';
import Icon from '../../shared/Icon.vue';
import MeetingInfoEditor from '../meetings/MeetingInfoEditor.vue';
import {usePublicationDestinations} from './usePublicationDestinations';
import {canPrepareFinalInformation} from './final-information';
import {computed,shallowRef,ref,watch,onUnmounted} from 'vue';import {useApplication} from '../../application';import {usePublication} from './usePublication';import type {SavedMeeting} from '../../shared/api/meeting-info';import type {MinutesCurrent} from '../../shared/api/minutes-saved';import type {components} from '../../shared/api/generated';import {ApiError} from '../../shared/api/client';
const props=defineProps<{meetingId:string;owner:boolean;locked:boolean;targetLabels?:Record<string,string>;meetingInfo?:SavedMeeting;savedMinutes?:MinutesCurrent;stage?:string}>();const emit=defineEmits<{changed:[];denied:[cause:unknown];editInfo:[];published:[];infoSaved:[];navigate:[stage:string]}>();const app=useApplication();
const p=usePublication({...app.publications,authorize:async(id,s)=>{const n=await app.workspace.navigation(id,s);return n.relation!=='OWNER'?false:n.navigationState==='PUBLISHED_READ_ONLY'?'READ_ONLY':n.navigationState==='CHECK_PRODUCER';}},()=>app.session.current.value?.actor.enterpriseId??null,()=>props.meetingId,()=>props.owner,()=>app.minutesScopeReady.value,()=>props.locked,app.journals,cause=>{clear();emit('denied',cause);});
const canPrepareFinal=computed(()=>canPrepareFinalInformation(p.readiness.value));
const readinessDialog=ref<HTMLDialogElement>(),embeddedInfo=ref<InstanceType<typeof MeetingInfoEditor>>(),successDialog=ref<HTMLDialogElement>(),submitted=ref(false),successShown=ref(false);let pollEpoch=0,pollTimer:ReturnType<typeof setTimeout>|null=null;
const librarySearch=ref(''),error=ref(''),reading=ref(false),optional=ref<string[]>([]),requirementPage=ref(0),showRequirements=ref(false),attempts=shallowRef<components['schemas']['AttemptPage']|null>(null);let epoch=0,controller:AbortController|null=null;
const remoteLabels:Record<string,string>={SUCCESS:'知识库已保存',FAILED:'知识库已拒绝',UNKNOWN:'结果待查回',NOT_OBSERVED:'尚未确认'};
const applicationLabels:Record<string,string>={APPLIED:'已应用',PENDING:'等待应用',DISCARDED:'未应用',FAILED:'应用失败',NOT_APPLIED:'尚未应用'};
const stateLabels:Record<string,string>={READY:'等待发布',RUNNING:'正在发布',RECONCILING:'正在查回结果',FAILED:'发布失败',SUCCEEDED:'已发布'};
const blockerLabels:Record<string,string>={BODY_REQUIRED:'请先生成或保存纪要正文',ELEMENT_SET_REQUIRED:'请先生成并采用核心要素',GENERATION_REQUIRED:'内容或设置已变更，请重新生成',SETTINGS_REQUIRED:'请先选择模板与初始设置',REVIEW_REQUIRED:'请完成下方标为待完成的必需审阅',PENDING_CANDIDATE:'请先处置待决定候选',OUTSTANDING_GENERATION:'请等待当前处理任务结束',TRANSCRIPT_CONFIRMATION_REQUIRED:'请先确认已保存转写',CORRECTIONS_PENDING:'请先核对并处理待确认的转写纠错建议。',CORRECTION_UNAVAILABLE:'转写校正服务尚不可用',MATERIALS_UNAVAILABLE:'背景材料暂不可读取，请核对会议文件',PUBLISHED:'会议已发布，请查看已发布纪要',PUBLICATION_BUSY:'发布任务尚未结束，请查回当前结果',MEETING_INFO_REQUIRED:'请补全并保存会议信息',ROSTER_CONFIRMATION_REQUIRED:'请确认已保存的参会名单',SAVED_SOURCE_OR_SETTINGS_STALE:'来源或设置已变化，请重新生成并采用纪要',SENSITIVITY_UNRESOLVED:'请核对敏感信息并保存排除选择后重新生成',EXCLUDED_SOURCE_USED:'当前纪要包含已排除来源，请重新生成并采用',TASK11_NOT_INSTALLED:'最终确认服务尚未启用'};
const status=computed(()=>p.current.value?.publication),message=computed(()=>p.error.value instanceof Error?p.error.value.message:'发布状态暂不可用。');
const destinations=usePublicationDestinations(app.publications,()=>app.session.current.value?.actor.enterpriseId??null,()=>props.meetingId,()=>props.owner&&app.minutesScopeReady.value,()=>props.locked||!!status.value||p.busy.value,cause=>p.deny(cause),app.journals);
const selectedDestination=destinations.selection,previewDialog=ref<HTMLDialogElement>(),publicationSaveMessage=ref('');
const selectedPath=computed(()=>selectedDestination.value?[selectedDestination.value.libraryName,...selectedDestination.value.path.map(f=>f.name)].join(' / '):'请选择发布位置');
async function openPreview(){const actor=app.session.current.value?.actor.enterpriseId,id=props.meetingId;await p.reload();if(actor!==app.session.current.value?.actor.enterpriseId||id!==props.meetingId||!p.final.value?.confirmation||!p.final.value.body||!p.final.value.information||p.error.value)return;previewDialog.value?.showModal();}
watch(()=>p.final.value?.confirmation?.id,()=>{previewDialog.value?.close();emit('changed');});
watch(()=>status.value,value=>{if(value?.rawState==='SUCCEEDED'&&value.remoteOutcome==='SUCCESS'&&value.applicationOutcome==='APPLIED'){emit('published');if(!successShown.value&&(submitted.value||p.command.snapshot.value?.operation==='PUBLICATION_SUBMIT')){successShown.value=true;successDialog.value?.showModal();}}});
async function read<T>(fn:(s:AbortSignal)=>Promise<T>,accept:(v:T)=>void){const turn=++epoch;controller?.abort();const request=new AbortController();controller=request;reading.value=true;error.value='';try{const v=await fn(request.signal);if(turn===epoch)accept(v);}catch(cause){if(turn===epoch){if(cause instanceof ApiError&&[401,403].includes(cause.status)){p.deny(cause);}error.value=cause instanceof Error?cause.message:'目录暂不可用。';}}finally{if(turn===epoch)reading.value=false;}}
function clear(){successDialog.value?.close();submitted.value=false;successShown.value=false;publicationSaveMessage.value='';previewDialog.value?.close();destinations.clear();librarySearch.value='';readinessDialog.value?.close();showRequirements.value=false;epoch++;controller?.abort();optional.value=[];attempts.value=null;error.value='';reading.value=false;}
async function run(fn:()=>Promise<void>){try{await fn();if(!p.error.value)emit('changed');}catch(cause){error.value=cause instanceof Error?cause.message:'操作暂不可用。';}}
function publish(){const selected=selectedDestination.value;if(!selected||!destinations.canSubmit.value){error.value='请先核对真实知识库或文件夹。';return;}submitted.value=true;void run(()=>p.submit({providerId:selected.providerId,libraryId:selected.libraryId,folderId:selected.folderId}));}
function loadAttempts(cursor:string|null=null){const id=status.value?.publicationId;if(id)void read(s=>app.publications.attempts(props.meetingId,id,cursor,s),v=>attempts.value=v);}
function reloadForStage(){if(!app.session.current.value)return;p.restoreOriginal();if(!props.stage||['confirm','publish','published'].includes(props.stage)||props.savedMinutes?.observation.readOnlyReason==='PUBLISHED'||p.command.snapshot.value)void p.reload();}
const stop=watch(()=>[app.session.current.value?.actor.enterpriseId,props.meetingId,props.owner,app.minutesScopeReady.value],()=>{clear();reloadForStage();},{immediate:true,flush:'sync'});onUnmounted(()=>{pollEpoch++;if(pollTimer)clearTimeout(pollTimer);stop();clear();destinations.dispose();p.dispose();});

watch(()=>status.value?.publicationId,id=>{if(!id)return;const turn=++pollEpoch;let attempts=0;async function tick(){if(turn!==pollEpoch||!status.value||status.value.publicationId!==id)return;if(['READY','RUNNING','RECONCILING'].includes(status.value.rawState)&&attempts++<30){await p.reload();if(turn===pollEpoch)pollTimer=setTimeout(tick,2000);}}pollTimer=setTimeout(tick,1500);});
watch(()=>props.stage,reloadForStage);
watch(()=>props.savedMinutes?.observation.readOnlyReason,reason=>{if(reason==='PUBLISHED'&&props.stage&&!['confirm','publish','published'].includes(props.stage))reloadForStage();});
const visibleLibraries=computed(()=>destinations.libraries.value?.items.filter(x=>x.name.toLocaleLowerCase().includes(librarySearch.value.trim().toLocaleLowerCase()))??[]);
async function confirmFinal(){if(embeddedInfo.value){const ready=await embeddedInfo.value.prepareFinal();if(!ready)return;emit('infoSaved');await p.reload();}await run(()=>p.confirm(optional.value));if(p.final.value?.confirmation&&!p.error.value)emit('navigate','publish');}
watch(()=>[props.stage,p.final.value?.confirmation?.id,status.value?.publicationId,props.owner,app.minutesScopeReady.value,props.locked],()=>{if(props.stage==='publish'&&props.owner&&app.minutesScopeReady.value&&!props.locked&&p.final.value?.confirmation&&!status.value&&!destinations.libraries.value&&!destinations.busy.value&&!destinations.error.value)void destinations.loadLibraries();});
const canSaveInformation=computed(()=>props.stage==='confirm'&&props.owner&&!props.locked&&!p.final.value?.confirmation&&!!embeddedInfo.value?.canPrepare&&!p.busy.value);
async function saveInformation(){return canSaveInformation.value?(await embeddedInfo.value?.saveInformation())??false:false;}
const canSaveConfiguration=computed(()=>props.stage==='publish'&&props.owner&&app.minutesScopeReady.value&&!props.locked&&!p.busy.value&&!status.value&&!destinations.busy.value&&!destinations.error.value);
function saveConfiguration(){if(!canSaveConfiguration.value)return false;if(!selectedDestination.value){publicationSaveMessage.value='尚未选择发布位置';return false;}const saved=destinations.saveSelection();publicationSaveMessage.value=saved?'发布位置已保存在此标签页':'发布位置暂未保存，请重新选择';return saved;}
defineExpose({saveConfiguration,canSaveConfiguration,publicationSaveMessage,saveInformation,canSaveInformation,informationSaveMessage:computed(()=>embeddedInfo.value?.informationSaveMessage??'')});
function openReadiness(){showRequirements.value=true;readinessDialog.value?.showModal();}
const fixedDock=ref<HTMLElement>();useFixedDockHeight(fixedDock);
</script>
<template><section class="publication" :class="{'m19-published-summary':stage==='published'}"><p v-if="p.error.value" role="alert">{{message}}</p><p v-if="error" role="alert">{{error}}</p>
 <template v-if="stage==='confirm'"><div class="ac-confirm-grid"><section class="card ac-confirm-info"><div class="card-h"><h3 class="card-t">会议信息</h3></div><div class="card-p"><MeetingInfoEditor v-if="owner&&!p.final.value?.confirmation" ref="embeddedInfo" presentation="final" :meeting-id="meetingId" :eligible="true" @saved="emit('infoSaved');p.reload()"/><template v-else><label class="form-label">会议名称 <span class="required">*</span></label><input class="input" readonly :value="meetingInfo?.name??''"/><label class="form-label mt16">会议日期 <span class="required">*</span></label><input class="input" type="date" readonly :value="meetingInfo?.occurredOn??''"/><label class="form-label mt16">会议分类 <span class="required">*</span></label><input class="input" readonly :value="meetingInfo?.category??''"/><label class="form-label mt16">会议摘要</label><div class="confirm-description">{{meetingInfo?.summary||'暂无会议摘要'}}</div><label class="form-label mt16">参会人 <span class="required">*</span></label><div class="confirm-participants"><span v-for="person in meetingInfo?.confirmedRoster??[]" :key="person.memberId" class="tag orange">{{person.displayName}}</span><span v-if="!meetingInfo?.confirmedRosterId" class="muted">尚未确认参会人员</span></div><p class="small muted mt12">最终确认使用已保存信息与已确认名单。</p></template></div></section><section class="card ac-confirm-preview"><div class="card-h"><h3 class="card-t">纪要预览</h3></div><div class="card-p ac-confirm-body"><template v-if="savedMinutes?.body"><pre>{{savedMinutes.body.title+'\n\n'+savedMinutes.body.body}}</pre></template><div v-else class="empty">尚无已保存纪要</div></div></section></div>
 <section v-if="owner&&p.readiness.value&&!canPrepareFinal" class="banner error mt16" role="alert"><div><strong>请先完成确认检查</strong><div v-for="blocker in p.readiness.value.blockers" :key="blocker">{{blockerLabels[blocker]??blocker}}</div><button type="button" class="btn sm mt8" @click="openReadiness">查看检查明细</button></div></section>
 <dialog ref="readinessDialog" class="publication-check-mask mask" role="presentation" @cancel.self.prevent="readinessDialog?.close()" @click.self="readinessDialog?.close()"><section class="modal lg" role="dialog" aria-modal="true" aria-labelledby="final-check-title"><header class="modal-h"><h3 id="final-check-title" class="m-t">最终确认检查</h3><button type="button" class="m-x" aria-label="关闭最终确认检查" @click="readinessDialog?.close()"><Icon name="x" :size="18"/></button></header><div class="modal-b"><div class="card card-p ac-confirm-check"><div class="between confirmation-check-heading"><h3>确认检查</h3><button v-if="owner&&p.readiness.value" type="button" class="confirmation-details-toggle" :aria-expanded="showRequirements" @click="showRequirements=!showRequirements">{{showRequirements?'收起检查明细':'查看检查明细'}}</button></div><template v-if="owner&&p.readiness.value"><div v-if="!canPrepareFinal" class="ac-confirm-errors"><div v-for="b in p.readiness.value.blockers" :key="b" class="ac-error mb8" :title="b">{{blockerLabels[b]??b}}</div></div><div v-else class="banner success">转写、纪要及材料版本校验通过；提交时将再次校验。</div><div v-if="showRequirements" class="confirmation-check-details"><p class="small muted mt12">待处置候选 {{p.readiness.value.pendingCandidateIds.length}} 项 · 未完成任务 {{p.readiness.value.outstandingTaskIds.length}} 项</p><ul v-if="p.readiness.value.required.length" class="ac-confirm-requirements"><li v-for="r in p.readiness.value.required.slice(requirementPage*20,(requirementPage+1)*20)" :key="r.targetId+r.reviewKind">{{r.reviewKind==='ACTION_FIELDS'?'行动字段':'全文来源'}} · {{targetLabels?.[r.targetId]??'当前条目'}} · {{r.satisfied?'已满足':'待完成'}}</li></ul><div v-if="p.readiness.value.required.length>20" class="flex"><button v-if="requirementPage>0" class="btn sm" @click="requirementPage--">上一页条件</button><button v-if="(requirementPage+1)*20<p.readiness.value.required.length" class="btn sm" @click="requirementPage++">下一页条件</button></div><details v-if="p.readiness.value.optionalReviewIds.length" class="mt12"><summary>选择一并冻结的可选审阅</summary><label v-for="id in p.readiness.value.optionalReviewIds" :key="id"><input v-model="optional" type="checkbox" :value="id"/> {{id}}</label></details></div></template><p v-else class="small muted">正在检查最终确认条件…</p><p class="small muted mt12">最终确认将保存会议信息、确认参会名单并更新访问权限；会议名称、会议日期和分类必填，摘要和参会名单可为空。</p></div></div><footer class="modal-f"><button type="button" class="btn primary" @click="readinessDialog?.close()">完成</button></footer></section></dialog>
 <footer v-if="owner" ref="fixedDock" class="acf-dock"><div class="acf-inner"><div class="acf-hint confirmation-hint" role="button" tabindex="0" aria-label="查看最终确认检查明细" title="查看最终确认检查明细" @click="openReadiness" @keydown.enter.prevent="openReadiness" @keydown.space.prevent="openReadiness">{{p.final.value?.confirmation?'当前版本已最终确认。':'最终确认将保存会议信息、确认参会名单并更新访问权限；会议名称、会议日期和分类必填。'}}</div><div class="acf-actions"><button class="btn" @click="emit('navigate','minutes')">返回纪要编辑</button><button v-if="p.final.value?.confirmation" class="btn primary" @click="emit('navigate','publish')">继续发布 ›</button><button v-else class="btn primary" :disabled="locked||p.busy.value||(!canPrepareFinal||!embeddedInfo?.canPrepare)" @click="confirmFinal">最终确认并继续发布</button></div></div></footer></template>
 <template v-if="stage==='publish'"><div class="two-col ac-publish-grid"><section class="card ac-publish-location"><div class="card-h"><h3 class="card-t">选择发布位置</h3></div><div class="card-p">
 <div class="pub-location-search"><div class="search-box"><Icon name="search" :size="13"/><input v-model="librarySearch" class="input" aria-label="搜索发布知识库" :placeholder="destinations.libraries.value?.hasMore?'搜索已加载知识库':'搜索知识库'"/><button type="button" class="pub-search-clear" :hidden="!librarySearch" aria-label="清空知识库搜索" title="清空搜索" @click="librarySearch='' "><Icon name="x" :size="13"/></button></div></div>
 <p class="small muted pub-location-count">{{destinations.libraries.value?.hasMore?'已加载可发布知识库':'可发布知识库'}} {{visibleLibraries.length}} 个</p><p v-if="destinations.busy.value" class="small muted" role="status">正在读取目录…</p>
 <div class="pub-location-list"><div v-for="lib in visibleLibraries" :key="lib.id" class="ac-publish-library" :class="{'is-current':selectedDestination?.libraryId===lib.id}"><button type="button" class="radio-row pub-location-item" :class="{sel:selectedDestination?.libraryId===lib.id&&!selectedDestination.path.length}" :aria-pressed="selectedDestination?.libraryId===lib.id&&!selectedDestination.path.length" :disabled="locked||!!status||p.busy.value" @click="destinations.selectLibrary(lib)"><span class="radio-dot"></span><span class="pub-library-copy"><b>{{lib.name}}</b><small></small></span></button>
 <div v-if="selectedDestination?.libraryId===lib.id" class="ac-publish-library-folders"><ul v-if="destinations.rows(lib).length" class="tree"><li v-for="row in destinations.rows(lib)" :key="row.folder.id" :style="{marginLeft:row.depth*22+'px'}"><div class="tree-node" :class="{sel:selectedDestination?.folderId===row.folder.id}"><button type="button" class="t-caret folder-expand" :class="{open:row.expanded}" :disabled="locked||!!status||row.knownEmpty" :aria-label="(row.expanded?'收起':'展开')+'文件夹 '+row.folder.name" :aria-expanded="row.expanded" @click="destinations.toggle(lib,row.folder)">{{row.knownEmpty?'':'▸'}}</button><button type="button" class="folder-select" :disabled="locked||!!status||p.busy.value" :aria-pressed="selectedDestination?.folderId===row.folder.id" @click="destinations.selectFolder(lib,row.folder,row.path)"><Icon name="folder" :size="14"/> {{row.folder.name}}</button></div><button v-if="destinations.branch(lib,row.folder.id)?.expanded&&destinations.branch(lib,row.folder.id)?.page.hasMore" type="button" class="btn sm" :disabled="destinations.busy.value||locked||!!status" @click="destinations.loadBranch(lib,row.folder.id,destinations.branch(lib,row.folder.id)!.page.nextCursor)">更多子文件夹</button></li></ul><p v-else-if="destinations.branch(lib,lib.rootFolderId)&&!destinations.busy.value&&!destinations.error.value" class="small muted">暂无文件夹，可直接发布到此知识库。</p><button v-if="destinations.branch(lib,lib.rootFolderId)?.page.hasMore" type="button" class="btn sm" :disabled="destinations.busy.value||locked||!!status" @click="destinations.loadBranch(lib,lib.rootFolderId,destinations.branch(lib,lib.rootFolderId)!.page.nextCursor)">更多文件夹</button></div></div>
 <p v-if="destinations.libraries.value&&!visibleLibraries.length" class="empty">未找到可发布的知识库，请调整搜索条件。</p></div>
 <button v-if="destinations.libraries.value?.hasMore" type="button" class="btn sm" :disabled="destinations.busy.value||locked||!!status" @click="destinations.loadLibraries(destinations.libraries.value.nextCursor)">更多知识库</button>
 <p v-if="destinations.error.value" role="alert">{{destinations.error.value instanceof Error?destinations.error.value.message:'目录读取失败。'}} <button type="button" class="btn sm" :disabled="destinations.busy.value||locked||!!status" @click="destinations.retry()">重试读取目录</button></p><p v-if="destinations.storageMessage.value" class="small muted mt12">{{destinations.storageMessage.value}}</p>
 <p class="small muted mt12">文件夹继承知识库权限；仅可选择已有文件夹，不能在此创建、修改或删除。</p></div></section>
 <div class="grid" style="gap:16px"><section class="card"><div class="card-h"><h3 class="card-t">发布配置</h3></div><div class="card-p"><div class="field"><label>发布路径</label><div class="card card-p pub-selected-path"><b>{{selectedPath}}</b></div></div><div class="field"><label for="publication-frozen-title">文档标题</label><input id="publication-frozen-title" class="input" readonly :value="p.final.value?.body?.title??''" title="标题与最终确认一致；如需修改，请返回纪要编辑并重新确认。"/></div>
 <div class="banner info pub-permission-hint"><Icon name="lock" :size="15"/> 正式文档继承目标知识库权限；原录音、会议转写和引用材料仍分别校验访问权限。</div><div class="divider"></div><div class="grid pub-frozen-facts"><div class="between"><span class="muted">来源会议</span><span class="mono small">{{meetingId}}</span></div><div class="between"><span class="muted">证据完整性</span><span class="tag" :class="p.final.value?.provenanceVerified?'green':'amber'">{{p.final.value?.provenanceVerified?'冻结版本与来源已核验':'请先完成最终确认'}}</span></div><div class="between"><span class="muted">权限</span><span class="tag navy">继承知识库库级权限</span></div></div><div class="mt12"><button type="button" class="btn" :disabled="!p.final.value?.confirmation||!p.final.value.body||p.busy.value" @click="openPreview"><Icon name="eye" :size="14"/> 最终文档预览</button></div></div></section></div></div>
 <dialog ref="previewDialog" class="publication-check-mask mask" role="presentation" @cancel.self.prevent="previewDialog?.close()" @click.self="previewDialog?.close()"><section class="modal lg" role="dialog" aria-modal="true" aria-labelledby="publication-preview-title"><header class="modal-h"><h3 id="publication-preview-title" class="m-t">最终文档预览（发布版）</h3><button type="button" class="m-x" aria-label="关闭最终文档预览" @click="previewDialog?.close()"><Icon name="x" :size="18"/></button></header><div class="modal-b"><template v-if="p.final.value?.body&&p.final.value.information"><div class="publication-preview-content"><pre class="publication-frozen-text">{{p.final.value.body.title+'\n\n'+p.final.value.body.body}}</pre><dl class="publication-preview-metadata"><dt>发布路径</dt><dd>{{selectedPath}}</dd><dt>会议名称</dt><dd>{{p.final.value.information.name}}</dd><dt>会议日期</dt><dd>{{p.final.value.information.occurredOn??'未填写'}}</dd><dt>会议摘要</dt><dd>{{p.final.value.information.summary??'未填写'}}</dd><dt>参会人</dt><dd>{{p.final.value.information.roster.map(person=>person.displayName).join('、')||'空名单'}}</dd><dt>最终确认编号</dt><dd class="mono">{{p.final.value.confirmation?.id}}</dd></dl></div></template><p v-else role="alert">最终确认预览暂不可读取，请关闭后重试。</p></div><footer class="modal-f"><button type="button" class="btn primary" @click="previewDialog?.close()">关闭预览</button></footer></section></dialog>
 <footer v-if="owner" ref="fixedDock" class="acf-dock"><div class="acf-inner"><span class="acf-hint">{{selectedDestination?'请核对发布配置，确认后发布到知识库；重复提交不会重复创建文档。':'请选择发布知识库，也可继续选择库内文件夹。'}}</span><div class="acf-actions"><button class="btn primary" :disabled="!destinations.canSubmit.value||locked||p.busy.value||!!status||!p.final.value?.confirmation" @click="publish">发布到知识库</button></div></div></footer></template>
 <article v-if="status" class="card publication-status"><div class="between"><h3>{{stateLabels[status.rawState]??'发布状态'}}</h3><button class="btn sm" :disabled="p.busy.value" @click="run(p.reload)">刷新最终状态</button></div><p class="small muted">{{remoteLabels[status.remoteOutcome]??status.remoteOutcome}} · {{applicationLabels[status.applicationOutcome]??status.applicationOutcome}}</p><p v-if="status.remoteOutcome==='UNKNOWN'">远端结果尚未确定。请刷新查询，当前不能再次发送。</p><p v-if="status.applicationOutcome==='FENCED_MANUAL'">该发布关联需要人工处理，当前页面只提供结果查看。</p><a v-if="status.officialDocumentUrl" class="btn primary mt12" :href="status.officialDocumentUrl" target="_blank" rel="noopener">查看正式文档 ↗</a><p v-else class="small muted">正式文档入口当前不可用。</p><button v-if="owner&&status.rawState==='SUCCEEDED'&&p.final.value?.observation&&app.governanceCommands" class="btn mt12" @click="app.governanceCommands.open(status.publicationId,p.final.value!.observation!.revisionToken)">撤回 / 废止与治理历史</button><details v-if="owner" class="mt12"><summary @click="loadAttempts()">发布尝试记录</summary><ul v-if="attempts"><li v-for="a in attempts.items" :key="a.attemptId">{{a.kind}} · {{a.remoteOutcome}} · {{a.applicationOutcome}} · {{a.createdAt}}</li></ul><button v-if="attempts?.hasMore" class="btn sm" @click="loadAttempts(attempts.nextCursor)">下一页尝试</button></details></article>
 <p v-if="p.command.state.value==='ACKNOWLEDGED'" class="small muted">{{p.command.snapshot.value?.operation==='FINAL_CONFIRM'?'已收到原最终确认回执，冻结版本以当前读取结果为准。':'已收到原操作回执；发布是否完成以上方当前状态为准。'}}</p><button v-if="p.command.snapshot.value&&['PREPARED','UNCERTAIN'].includes(p.command.state.value)" class="btn" :disabled="p.busy.value" @click="run(p.retry)">{{p.command.snapshot.value.operation==='PUBLICATION_SUBMIT'?'查回原发布状态':'查回原最终确认'}}</button><button v-if="['CONFLICT','REJECTED'].includes(p.command.state.value)" class="btn" @click="p.reset();p.reload()">重新读取后再决定</button>
<Teleport to="body"><dialog ref="successDialog" class="publication-check-mask mask" role="presentation" @cancel.self.prevent="successDialog?.close()" @click.self="successDialog?.close()"><section class="modal pub-success-modal" role="dialog" aria-modal="true" aria-labelledby="publication-success-title"><header class="modal-h"><button type="button" class="m-x" aria-label="关闭发布成功提示" @click="successDialog?.close()"><Icon name="x" :size="18"/></button></header><div class="modal-b"><div class="pub-success-body"><div class="pub-success-icon" aria-hidden="true"><svg viewBox="0 0 64 64" width="64" height="64"><circle cx="32" cy="32" r="30" fill="#E6F7ED"/><path d="m19 32 9 9 18-19" fill="none" stroke="#00B255" stroke-width="4" stroke-linecap="round" stroke-linejoin="round"/></svg></div><h2 id="publication-success-title">发布成功</h2><p>会议纪要已发布到知识库，已发布会议不支持修改。</p><p v-if="selectedDestination" class="mt12">{{selectedPath}}</p><p v-else class="small muted mt12">发布编号：<span class="mono">{{status?.publicationId}}</span></p><p v-if="status?.officialDocumentUrl" class="mt12"><a class="pub-success-path" :href="status.officialDocumentUrl" target="_blank" rel="noopener">查看正式文档</a></p></div></div><footer class="modal-f"><button type="button" class="btn primary" @click="successDialog?.close()">知道了</button></footer></section></dialog></Teleport></section></template>
